<div class="mb-6 flex items-end justify-between"><div><p class="text-sm font-medium text-blue-600">Asistencia</p><h1 class="text-2xl font-bold">Historial</h1></div><a href="index.php?url=incidencias" class="text-sm font-semibold text-blue-600">Justificaciones e incidencias</a></div>
<form class="mb-5 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:grid-cols-4"><input type="hidden" name="url" value="asistencia_historial"><label class="form-label">Desde<input type="date" name="fecha_inicio" value="<?= htmlspecialchars($filtros['fecha_inicio']) ?>" class="form-input"></label><label class="form-label">Hasta<input type="date" name="fecha_fin" value="<?= htmlspecialchars($filtros['fecha_fin']) ?>" class="form-input"></label><label class="form-label">Estado<select name="estado" class="form-input"><option value="">Todos</option><?php foreach(['PUNTUAL','TARDANZA','FALTA','JUSTIFICADO','PERMISO','LICENCIA','SALIDA_ANTICIPADA','INCOMPLETO'] as $e): ?><option <?= $filtros['estado']===$e?'selected':'' ?>><?= $e ?></option><?php endforeach; ?></select></label><button class="self-end rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Filtrar</button></form>
<section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table data-datatable data-page-options="5,10,25,50" data-order="0:desc,2:desc" class="min-w-full text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-4 py-3">Fecha</th><th class="px-4 py-3">Persona</th><th class="px-4 py-3">Entrada</th><th class="px-4 py-3">Salida</th><th class="px-4 py-3">Estado</th><th class="px-4 py-3">Tardanza</th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach($asistencias as $a): $estado=$a['estado']; $colorEstado=['PUNTUAL'=>'bg-emerald-100 text-emerald-700','TARDANZA'=>'bg-amber-100 text-amber-800','FALTA'=>'bg-red-100 text-red-700','JUSTIFICADO'=>'bg-sky-100 text-sky-700','PERMISO'=>'bg-violet-100 text-violet-700','INCOMPLETO'=>'bg-orange-100 text-orange-700','LICENCIA'=>'bg-slate-200 text-slate-700','SALIDA_ANTICIPADA'=>'bg-pink-100 text-pink-700'][$estado]??'bg-slate-100 text-slate-700'; ?><tr><td class="px-4 py-3 text-slate-600"><?= htmlspecialchars($a['fecha']) ?></td><td class="px-4 py-3 font-medium"><?= htmlspecialchars($a['persona']) ?></td><td class="px-4 py-3"><?= htmlspecialchars($a['hora_entrada']?:'—') ?></td><td class="px-4 py-3"><?= htmlspecialchars($a['hora_salida']?:'—') ?></td><td class="px-4 py-3"><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= $colorEstado ?>"><?= htmlspecialchars($estado) ?></span></td><td class="px-4 py-3"><?= (int)$a['minutos_tardanza'] ?> min.</td></tr><?php endforeach; ?><?php if(!$asistencias): ?><tr><td colspan="6" class="px-5 py-12 text-center text-slate-500">No hay registros para los filtros seleccionados.</td></tr><?php endif; ?></tbody></table></div></section>
